<template>
  <div class="contact">
    <Navbar :currentLang="currentLang" @change-lang="changeLang" />
    <section class="contact-hero">
      <h1>{{ t.nav.contact }}</h1>
      <p>{{ t.contact.subtitle }}</p>
    </section>
    <section class="contact-content">
      <div class="contact-form">
        <h2>{{ t.contact.form.title }}</h2>
        <p class="contact-form-text">{{ t.contact.form.text1 }}</p>
        <p class="contact-form-text">{{ t.contact.form.text2 }}</p>
        <form class="form" @submit.prevent="handleContactSubmit">
          <div class="form-group">
            <label for="name">{{ t.contact.form.name }}</label>
            <input type="text" id="name" v-model.trim="contactForm.name" :placeholder="t.contact.form.placeholder.name" required>
          </div>
          <div class="form-group">
            <label for="email">{{ t.contact.form.email }}</label>
            <input type="email" id="email" v-model.trim="contactForm.email" :placeholder="t.contact.form.placeholder.email" required>
          </div>
          <div class="form-group">
            <label for="phone">{{ t.contact.form.phone }}</label>
            <input type="tel" id="phone" v-model.trim="contactForm.phone" :placeholder="t.contact.form.placeholder.phone" required>
          </div>
          <div class="form-group">
            <label for="message">{{ t.contact.form.message }}</label>
            <textarea id="message" v-model.trim="contactForm.message" :placeholder="t.contact.form.placeholder.message" required></textarea>
          </div>
          <button type="submit" class="form-btn">{{ t.contact.form.btn }}</button>
        </form>
      </div>
      <div class="contact-info">
        <h2>{{ t.contact.info.title }}</h2>
        <ul class="contact-info-list">
          <li v-for="(item, index) in t.contact.info.items" :key="index">
            <i :class="['fas', 'fa-' + item.icon]"></i>
            <span>{{ item.text }}</span>
          </li>
        </ul>
      </div>
    </section>
    <Footer :currentLang="currentLang" />
  </div>
</template>

<script>
import Navbar from '../components/Navbar.vue'
import Footer from '../components/Footer.vue'
import { languages } from '../assets/languages.js'

export default {
  name: 'Contact',
  props: {
    currentLang: {
      type: String,
      default: 'zh'
    }
  },
  components: {
    Navbar,
    Footer
  },
  data() {
    return {
      recipientEmails: ['270302301@qq.com', 'colin270302301@gmail.com'],
      contactForm: {
        name: '',
        email: '',
        phone: '',
        message: ''
      }
    }
  },
  computed: {
    t() {
      return languages[this.currentLang] || languages.zh
    }
  },
  methods: {
    changeLang(lang) {
      this.$emit('change-lang', lang)
    },
    handleContactSubmit() {
      // Send notification to WeChat via Server酱
      const sendkey = 'SCT342335TIsFNci9EpNmO1RHEbA2amisa'
      const notifyTitle = `Astro Website Inquiry - ${this.contactForm.name || 'Visitor'}`
      const notifyDesp = `**Name:** ${this.contactForm.name}\n**Email:** ${this.contactForm.email}\n**Phone:** ${this.contactForm.phone}\n\n**Message:**\n${this.contactForm.message}`
      
      fetch(`https://sctapi.ftqq.com/${sendkey}.send?title=${encodeURIComponent(notifyTitle)}&desp=${encodeURIComponent(notifyDesp)}`)
        .then(response => response.json())
        .then(data => {
          console.log('Server酱通知发送成功:', data)
          // 显示成功提示
          alert('提交成功！我们会尽快与您联系。')
          // 清空表单
          this.contactForm = {
            name: '',
            email: '',
            phone: '',
            message: ''
          }
        })
        .catch(error => {
          console.error('Server酱通知发送失败:', error)
          // 显示失败提示
          alert('提交失败，请稍后重试。')
        })
    }
  }
}
</script>

